function isSidebarDashboard(entry) {
    return !!(entry && entry.id === "com.webos.app.homeconnect" &&
              entry.launchPointId === "com.webos.app.homeconnect_default");
}

function findSidebarDashboard(model) {
    if (!model) return null;
    for (var i = 0; i < model.count; i++) {
        var entry = model.get(i).entry;
        if (isSidebarDashboard(entry)) return entry;
    }
    return null;
}

function sidebarInputOrder(entries) {
    var ranked = [];
    for (var i = 0; i < entries.length; i++) {
        var e = entries[i], rank = -1;
        if (!e) continue;
        if (isSidebarDashboard(e)) rank = 300 + entries.length;
        else if (e.type === "input" && e.onClick && e.onClick.targetAppId === "com.webos.app.livetv") rank = 0;
        else if (e.type === "input" && /^HDMI_[0-9]+$/.test(e.inputId || "")) rank = 10 + parseInt(e.inputId.split("_")[1], 10);
        else if (e.type === "airplay") rank = 100;
        else if (e.type === "usb") rank = 200 + i;
        if (rank >= 0) ranked.push({index: i, rank: rank});
    }
    ranked.sort(function(a,b) { return a.rank - b.rank || a.index - b.index; });
    return ranked.map(function(v) { return v.index; });
}

function launchSidebarInput(entry) {
    if (isSidebarDashboard(entry)) {
        var dashboard = findSidebarDashboard(interfaces.launchPoints.launchPointsModel);
        if (dashboard) interfaces.launchPoints.doLaunch(dashboard);
        return;
    }
    if (entry && entry.type === "usb") {
        var devices = interfaces.connections.usbDevices || [];
        for (var i = 0; i < devices.length; i++) {
            var current = devices[i];
            if (current && current.deviceId === entry.deviceId && current.addOnInfo && current.addOnInfo.type === "usb" && !current.loading) {
                interfaces.application.launchPreview(current);
                return;
            }
        }
        return;
    }
    if (entry) interfaces.application.launchPreview(entry);
}

function sidebarAddonVisible(entry) {
    return !!(entry && !isSidebarDashboard(entry) && entry.type === "usb" && entry.addOnInfo);
}

function sidebarNativeEntries(inputs, devices, dashboard) {
    var entries = inputs.slice(), seen = {};
    for (var i = 0; i < devices.length; i++) {
        var e = devices[i];
        if (e && e.type === "usb" && e.deviceId && e.addOnInfo && e.addOnInfo.type === "usb" && !e.loading && !seen[e.deviceId]) {
            entries.push(e);
            seen[e.deviceId] = true;
        }
    }
    if (isSidebarDashboard(dashboard)) entries.push(dashboard);
    return entries;
}

function focusSidebar() {
    if (!root.nativeGridEnabled) return;
    var i = Math.max(0, Math.min(root.sidebarCurrentIndex, sidebarInputs.count - 1));
    var item = sidebarInputs.itemAt(i);
    if (item) item.forceActiveFocus();
    else sidebarSearch.forceActiveFocus();
}

function focusSidebarSearch() {
    if (!root.nativeGridEnabled || uiController.isRecentMode) return false;
    sidebarSearch.forceActiveFocus();
    return true;
}

function focusSidebarApps() {
    if (root.main && root.main.gridMode) root.main.gridView.forceActiveFocus();
}

function sidebarSearchAction() {
    var actions = systemProperties.topGlobalActions || [];
    for (var i = 0; i < actions.length; i++) {
        var obj = actions[i];
        if (obj.type === "search" && obj.onClick) {
            interfaces.application.launchApp(obj.onClick.targetAppId, obj.onClick.launchPointId, obj.onClick.launchParam || {}, "launcher");
            return;
        }
    }
}

