function nativeClockGeometry(expanded) {
    var g = expanded ? {height: 44, fontSize: 30, secondsFontSize: 12, y: 8, gap: 8, digitWidth: 20, colonWidth: 8, secondsDigitWidth: 8, secondsY: 8} :
                       {height: 104, fontSize: 152.5, secondsFontSize: 61, y: 32, gap: 16, digitWidth: 96, colonWidth: 40, secondsDigitWidth: 40, secondsY: -8};
    g.mainWidth = g.digitWidth * 4 + g.colonWidth;
    g.secondsWidth = g.secondsDigitWidth * 2;
    g.width = g.mainWidth + g.gap + g.secondsWidth;
    return g;
}
