// The full-screen wheel catcher must route grid events before shelf paging.
// Do not transfer focus on a wheel gesture, including at either scroll boundary.
if (root.nativeGridEnabled && root.main && root.main.gridMode &&
        wheel.y >= appListArea.y && wheel.y < appListArea.y + appListArea.height) {
    root.main.scrollGrid(delta);
