    return;
}

// Whole rows only. Reserve the stock Dashboard height (no scaling of its controls).
function gridAreaHeight(screenHeight, appY, rows, dashboardHeight, cellHeight, topSpace, gap, bottomSpace) {
    var available = screenHeight - appY - dashboardHeight - gap - bottomSpace - topSpace;
    var visibleRows = Math.max(1, Math.floor(available / cellHeight));
    return topSpace + Math.min(Math.max(1, rows), visibleRows) * cellHeight;
}

function getGridAppAreaHeight() {
    var appY = getHomeAppListAreaYPosition();
    var bottomSpace = styleSheet.getRValue(36);
    if (root.nativeAppsExpanded) return Math.max(0, root.height - appY - bottomSpace);
    var preferred = root.main ? root.main.preferredHeight : styleSheet.getRValue(480);
    return nativeAppAreaHeight(root.height, appY, Math.min(preferred, styleSheet.getRValue(580)),
                               root.nativeInputsHeight, root.nativeInputsGap, bottomSpace);
}

function nativeAppAreaHeight(screenHeight, appY, preferred, inputsHeight, gap, bottomSpace) {
    return Math.max(0, Math.min(preferred, screenHeight - appY - inputsHeight - gap - bottomSpace));
}

if (root.nativeGridEnabled) return styleSheet.getRValue(root.nativeAppsExpanded ? 90 : 400);
if (root.compactHeader) {
    return topArea.y + topArea.height;
}

onGridModeChanged: {
