}

function restoreGridFocus() {
    // EditMainMenu.closeEdit selects its stock delegate after goToState.
    // Restore normal focus once that synchronous native handler has finished.
    if (!root.gridMode || !root.activeFocus || !root.visible || !rootWindow.active) return;
    root.selectedLaunchPointId = "";
