// Only presentation metadata is sorted; native model entries are never copied or moved.
function categoryLayout(entries, expanded) {
    // One flat presentation in stable app order; original LaunchPoints stay untouched.
    var preferred = ["com.crunchyroll.webapp", "netflix", "youtube.leanback.v4", "io.strem.tv", "amazon", "org.moonfin.webos", "com.disney.disneyplus-prod", "com.apple.appletv", "com.limelight.webos", "org.webosbrew.hbchannel", "com.biliwebos.app"];
    var ranked = [], slots = [], order = [];
    var trailingTools = ["com.webos.app.discovery", "com.webos.app.mediadiscovery", "com.webos.app.browser"];
    var railOnlyOrHidden = ["com.webos.app.homeconnect", "com.webos.app.roomconnect", "amazon.alexa.view"];
    for (var i = 0; i < entries.length; i++) {
        var id = entries[i] ? entries[i].id || "" : "";
        if (typeof id !== "string" || !id) continue;
        if (railOnlyOrHidden.indexOf(id) >= 0) continue;
        var rank = preferred.indexOf(id);
        if (rank < 0) rank = trailingTools.indexOf(id) >= 0 ? 100 + trailingTools.indexOf(id) : preferred.length;
        // New apps from either store precede utilities, sorted by display name, never usage.
        var title = entries[i] && typeof entries[i].title === "string" ? entries[i].title : id;
        ranked.push({sourceIndex: i, id: id, titleKey: title.toLowerCase(), key: entries[i] ? entries[i].launchPointId || "" : "", rank: rank});
    }
    ranked.sort(function(a, b) {
        if (a.rank !== b.rank) return a.rank - b.rank;
        if (a.rank === preferred.length && a.titleKey !== b.titleKey) return a.titleKey < b.titleKey ? -1 : 1;
        if (a.id !== b.id) return a.id < b.id ? -1 : 1;
        if (a.key !== b.key) return a.key < b.key ? -1 : 1;
        return a.sourceIndex - b.sourceIndex;
    });
    var catalogCount = ranked.length;
    // Reserve the twelfth compact slot for the all-apps card.
    // Remaining native LaunchPoints stay in the expanded catalog.
    if (!expanded && ranked.length > 11) ranked = ranked.slice(0, 11);
    for (var n = 0; n < ranked.length; n++) {
        var sourceIndex = ranked[n].sourceIndex;
        var row = Math.floor(n / 6);
        slots[sourceIndex] = {sourceIndex: sourceIndex, col: n % 6, row: row, y: row * 276};
        order.push(sourceIndex);
    }
    var allAppsIndex = -1;
    if (!expanded) {
        allAppsIndex = entries.length;
        var position = order.length;
        slots[allAppsIndex] = {sourceIndex: allAppsIndex, col: position % 6, row: Math.floor(position / 6), y: Math.floor(position / 6) * 276};
        order.push(allAppsIndex);
    }
    var rows = Math.ceil(order.length / 6);
    return {slots: slots, order: order, headers: [], rows: rows, catalogCount: catalogCount, allAppsIndex: allAppsIndex,
            height: rows ? (rows - 1) * 276 + 260 : 0};
}

// Indices always address the original native model, not the display order.
function categoryTargetIndex(layout, index, direction, rtl) {
    if (!layout.order.length) return -1;
    var current = layout.slots[index];
    if (!current) return layout.order[0];
    var vertical = direction === "up" || direction === "down";
    var forward = direction === "down" || direction === (rtl ? "left" : "right");
    var best = -1;
    var distance = Infinity;
    for (var i = 0; i < layout.slots.length; i++) {
        var slot = layout.slots[i];
        if (!slot) continue;
        var delta = vertical ? slot.row - current.row : slot.col - current.col;
        if (!vertical && slot.row !== current.row) continue;
        if (forward ? delta <= 0 : delta >= 0) continue;
        var score = Math.abs(delta) * 100 + (vertical ? Math.abs(slot.col - current.col) : 0);
        if (score < distance || (score === distance && slot.col < layout.slots[best].col)) {
            best = i;
            distance = score;
        }
    }
    if (best >= 0) return best;
    return vertical ? -1 : (forward ? -2 : index);
}

function navigateGrid(direction) {
    var slot = root.categoryGeometry.slots[appGrid.currentIndex];
    if (root.gridMode && direction === (systemProperties.isRTLLocale ? "right" : "left") && slot && slot.col === 0) {
        uiController.mainView.focusSidebar();
        return true;
    }
    var next = categoryTargetIndex(root.categoryGeometry, appGrid.currentIndex, direction, systemProperties.isRTLLocale);
    if (next === -1) {
        if (root.allAppsExpanded && direction === "up") {
            gridBackButton.forceActiveFocus();
