    if (next >= 0 && next < mainList.count) mainList.currentIndex = next;
    appGrid.positionViewAtIndex(next, GridView.Contain);
    if (appGrid.currentItem) appGrid.currentItem.forceActiveFocus();
    if (next < mainList.count) root.getItemX();
    return true;
}

